    yamlFilename: "01-extract-multiple-tables.yaml",
    yamlCode:
      'input:\n  # Sequence through multiple tables in one pipeline\n  sequence:\n    inputs:\n      # Orders table\n      - sql_select:\n          driver: postgres  # Or: mysql, odbc, mssql\n          dsn: "postgres://${DB_USER}:${DB_PASSWORD}@${DB_HOST}:5432/${DB_NAME}?sslmode=require"\n          table: orders\n          columns: ["*"]\n          where: "updated_at >= CURRENT_DATE - INTERVAL \'1 day\'"\n        processors:\n          - mapping: |\n              root = this\n              root._table = "orders"\n              root._backup_type = "incremental"\n\n      # Inventory table (full backup - smaller table)\n      - sql_select:\n          driver: postgres\n          dsn: "postgres://${DB_USER}:${DB_PASSWORD}@${DB_HOST}:5432/${DB_NAME}?sslmode=require"\n          table: inventory\n          columns: ["*"]\n        processors:\n          - mapping: |\n              root = this\n              root._table = "inventory"\n              root._backup_type = "full"\n\n      # Order line items\n      - sql_select:\n          driver: postgres\n          dsn: "postgres://${DB_USER}:${DB_PASSWORD}@${DB_HOST}:5432/${DB_NAME}?sslmode=require"\n          table: order_items\n          columns: ["*"]\n          where: "created_at >= CURRENT_DATE - INTERVAL \'1 day\'"\n        processors:\n          - mapping: |\n              root = this\n              root._table = "order_items"\n              root._backup_type = "incremental"\n',
